parameters.jsCode:
// Pull the facts card networks weigh most heavily out of the Stripe dispute + charge.
const d = $input.first().json;
const charge = (d.charge && typeof d.charge === 'object') ? d.charge : {};
const card = (charge.payment_method_details && charge.payment_method_details.card) || {};
const checks = card.checks || {};
const tds = card.three_d_secure || null;
const billing = charge.billing_details || {};
const meta = charge.metadata || {};

// Stripe amounts are in minor units, except for zero-decimal currencies
const zeroDecimal = ['BIF','CLP','DJF','GNF','JPY','KMF','KRW','MGA','PYG','RWF','UGX','VND','VUV','XAF','XOF','XPF'];
const currency = (d.currency || '').toUpperCase();
const divisor = zeroDecimal.includes(currency) ? 1 : 100;
const toDate = (ts) => (ts ? new Date(ts * 1000).toISOString().slice(0, 10) : null);

// The WooCommerce Stripe Gateway stores the order ID in charge metadata
const orderId = meta.order_id || meta.orderId || meta.woocommerce_order_id || null;
const dueBy = d.evidence_details ? d.evidence_details.due_by : null;
const networkReasonCode = (d.payment_method_details && d.payment_method_details.card && d.payment_method_details.card.network_reason_code) || null;

return [{
  json: {
    disputeId: d.id,
    chargeId: charge.id || d.charge || null,
    livemode: d.livemode === true,
    status: d.status,
    reason: d.reason,
    networkReasonCode,
    amount: d.amount / divisor,
    currency,
    dueBy: toDate(dueBy),
    dueByIso: dueBy ? new Date(dueBy * 1000).toISOString() : null,
    daysLeft: dueBy ? Math.floor((dueBy * 1000 - Date.now()) / 86400000) : null,
    pastDue: dueBy ? dueBy * 1000 < Date.now() : false,
    submissionCount: d.evidence_details ? (d.evidence_details.submission_count || 0) : 0,
    chargeDate: toDate(charge.created),
    customerName: billing.name || (charge.shipping && charge.shipping.name) || null,
    customerEmail: billing.email || charge.receipt_email || meta.customer_email || null,
    billingAddress: billing.address || null,
    shippingAddress: (charge.shipping && charge.shipping.address) || null,
    card: {
      brand: card.brand || null,
      last4: card.last4 || null,
      wallet: card.wallet ? card.wallet.type : null,
      cvcCheck: checks.cvc_check || null,
      addressLine1Check: checks.address_line1_check || null,
      postalCodeCheck: checks.address_postal_code_check || null,
    },
    threeDSecure: tds ? { result: tds.result || null, version: tds.version || null, flow: tds.authentication_flow || null } : null,
    radar: charge.outcome ? { riskLevel: charge.outcome.risk_level || null, riskScore: charge.outcome.risk_score ?? null } : null,
    orderId: orderId ? String(orderId) : null,
    dashboardUrl: `https://dashboard.stripe.com/${d.livemode ? '' : 'test/'}disputes/${d.id}`,
  },
}];

// Combine Stripe, WooCommerce and Gmail data into one fact-only case file for the AI.
const cfg = $('Set Store Configuration').first().json;
const sig = $('Extract Payment Signals').first().json;

// ---- WooCommerce order (only exists when the charge carried an order ID)
let order = null;
if ($('Fetch WooCommerce Order').isExecuted) {
  const o = $('Fetch WooCommerce Order').first().json;
  if (o && o.id) order = o;
}

// ---- Address helper that understands both Stripe and WooCommerce formats
const addr = (a) => {
  if (!a) return null;
  const name = a.first_name ? `${a.first_name} ${a.last_name || ''}`.trim() : null;
  const parts = [name, a.company, a.address_1 || a.line1, a.address_2 || a.line2, a.city, a.state, a.postcode || a.postal_code, a.country];
  const out = parts.filter((p) => p && String(p).trim()).join(', ');
  return out || null;
};

// ---- Other orders from the same customer (strong evidence against "fraud" claims)
let priorOrders = [];
if (order && $('Fetch Customer Order History').isExecuted) {
  const email = ((order.billing && order.billing.email) || '').toLowerCase();
  priorOrders = $('Fetch Customer Order History').all()
    .map((i) => i.json)
    .filter((o) => o && o.id && o.id !== order.id && ((o.billing && o.billing.email) || '').toLowerCase() === email)
    .slice(0, 10)
    .map((o) => ({ number: o.number, date: (o.date_created || '').slice(0, 10), status: o.status, total: `${o.total} ${o.currency}` }));
}

// ---- Shipment tracking (WooCommerce Shipment Tracking / Advanced Shipment Tracking meta)
const metaVal = (key) => {
  const m = ((order && order.meta_data) || []).find((x) => x.key === key);
  return m ? m.value : null;
};
const trackingItems = metaVal('_wc_shipment_tracking_items');
const tracking = Array.isArray(trackingItems)
  ? trackingItems
      .map((t) => ({
        carrier: t.custom_tracking_provider || t.formatted_tracking_provider || t.tracking_provider || null,
        number: t.tracking_number || null,
        shippedOn: t.date_shipped ? new Date(Number(t.date_shipped) * 1000).toISOString().slice(0, 10) : null,
      }))
      .filter((t) => t.number)
  : [];

// ---- Customer emails found in Gmail
const emails = $('Search Customer Emails in Gmail').all()
  .map((i) => i.json)
  .filter((e) => e && e.id)
  .map((e) => ({
    date: e.internalDate ? new Date(Number(e.internalDate)).toISOString().slice(0, 10) : (e.date || null),
    from: e.From || e.from || null,
    subject: e.Subject || e.subject || null,
    snippet: String(e.snippet || '').slice(0, 300),
  }));

// ---- Order summary
const orderSummary = order ? {
  number: order.number,
  status: order.status,
  createdOn: (order.date_created || '').slice(0, 10),
  completedOn: (order.date_completed || '').slice(0, 10) || null,
  total: `${order.total} ${order.currency}`,
  paymentMethod: order.payment_method_title || null,
  customerIp: order.customer_ip_address || null,
  customerUserAgent: order.customer_user_agent || null,
  billingName: order.billing ? `${order.billing.first_name || ''} ${order.billing.last_name || ''}`.trim() : null,
  billingEmail: (order.billing && order.billing.email) || null,
  billingAddress: addr(order.billing),
  shippingAddress: addr(order.shipping),
  shippingMethod: (order.shipping_lines || []).map((s) => s.method_title).join(', ') || null,
  items: (order.line_items || []).map((li) => ({ name: li.name, sku: li.sku || null, quantity: li.quantity, total: li.total })),
  customerNote: order.customer_note || null,
  refunds: (order.refunds || []).map((r) => ({ amount: r.total, reason: r.reason || null })),
} : null;

// ---- Deterministic strengths / gaps (the AI must not invent these)
const strengths = [];
const gaps = [];
if (sig.threeDSecure && sig.threeDSecure.result === 'authenticated') strengths.push('Payment was authenticated with 3D Secure');
if (sig.card.cvcCheck === 'pass') strengths.push('CVC check passed');
if (sig.card.addressLine1Check === 'pass' || sig.card.postalCodeCheck === 'pass') strengths.push('Billing address (AVS) check passed');
if (sig.card.wallet) strengths.push(`Paid with ${sig.card.wallet} wallet`);
if (orderSummary && orderSummary.billingAddress && orderSummary.billingAddress === orderSummary.shippingAddress) strengths.push('Billing and shipping addresses match');
if (orderSummary && orderSummary.customerIp) strengths.push('Customer IP address recorded at checkout');
if (tracking.length) strengths.push(`Tracking number on file (${tracking.map((t) => t.carrier || 'carrier').join(', ')})`);
if (priorOrders.length) strengths.push(`${priorOrders.length} other order(s) from the same customer email`);
if (emails.length) strengths.push(`${emails.length} email(s) exchanged with the customer`);
if (!order) gaps.push('No matching WooCommerce order (order_id missing from Stripe charge metadata)');
if (order && !tracking.length && (order.shipping_lines || []).length) gaps.push('Order was shipped but no tracking number was found');
if (!emails.length) gaps.push('No customer emails found in Gmail');
if (orderSummary && orderSummary.refunds.length) gaps.push('Order already has a partial or full refund');

const caseFile = {
  store: {
    name: cfg.storeName,
    url: cfg.storeUrl,
    refundPolicyUrl: cfg.refundPolicyUrl,
    termsUrl: cfg.termsUrl,
    shippingPolicyUrl: cfg.shippingPolicyUrl,
    checkoutDisclosure: cfg.policyDisclosure,
  },
  dispute: {
    reason: sig.reason,
    networkReasonCode: sig.networkReasonCode,
    status: sig.status,
    amount: `${sig.amount} ${sig.currency}`,
    chargeDate: sig.chargeDate,
    respondBy: sig.dueBy,
  },
  payment: {
    customerName: sig.customerName,
    customerEmail: sig.customerEmail,
    card: sig.card,
    threeDSecure: sig.threeDSecure,
    radar: sig.radar,
    billingAddress: addr(sig.billingAddress),
  },
  order: orderSummary,
  tracking,
  priorOrders,
  customerEmails: emails,
  signals: { strengths, gaps },
};

return [{ json: { caseFile, strengths, gaps } }];

