parameters.jsCode:
// Translate the AI draft + raw facts into Stripe's dispute evidence fields.
const ai = $input.first().json.output || $input.first().json;
const cf = $('Assemble Dispute Case File').first().json.caseFile;
const cfg = $('Set Store Configuration').first().json;
const sig = $('Extract Payment Signals').first().json;

const ev = {};
const put = (key, value) => {
  if (value === null || value === undefined) return;
  const s = String(value).trim();
  if (s) ev[key] = s.slice(0, 20000); // Stripe limit per text field
};

const o = cf.order || {};
put('customer_name', o.billingName || sig.customerName);
put('customer_email_address', o.billingEmail || sig.customerEmail);
put('billing_address', o.billingAddress || cf.payment.billingAddress);
put('customer_purchase_ip', o.customerIp);
put('shipping_address', o.shippingAddress);

if (cf.tracking.length) {
  put('shipping_carrier', cf.tracking[0].carrier);
  put('shipping_tracking_number', cf.tracking.map((t) => t.number).join(', '));
  put('shipping_date', cf.tracking[0].shippedOn);
}

put('product_description', ai.product_description);

let letter = ai.rebuttal_letter || '';
if (ai.customer_communication_summary) letter += `\n\nCustomer communication:\n${ai.customer_communication_summary}`;
put('uncategorized_text', letter);

const policyLine = [
  cfg.refundPolicyUrl ? `Our refund policy is published at ${cfg.refundPolicyUrl}.` : '',
  cfg.policyDisclosure || '',
].join(' ');
put('refund_policy_disclosure', policyLine);
if (sig.reason === 'subscription_canceled') {
  put('cancellation_policy_disclosure', [cfg.termsUrl ? `Our cancellation terms are published at ${cfg.termsUrl}.` : '', cfg.policyDisclosure || ''].join(' '));
}
put('refund_refusal_explanation', ai.refund_refusal_explanation);
put('cancellation_rebuttal', ai.cancellation_rebuttal);
put('duplicate_charge_explanation', ai.duplicate_charge_explanation);

// Auto-submit only when you opted in AND the case is strong. Otherwise evidence is saved as a draft.
const autoSubmit = cfg.autoSubmit === true && ai.recommendation === 'submit' && ai.win_likelihood === 'high';

const params = Object.entries(ev).map(([k, v]) => `evidence[${k}]=${encodeURIComponent(v)}`);
params.push(`submit=${autoSubmit}`);
params.push(`metadata[evidence_prepared_by]=${encodeURIComponent('n8n')}`);

return [{
  json: {
    formBody: params.join('&'),
    evidenceFields: Object.keys(ev),
    autoSubmit,
    action: autoSubmit ? 'Submitted to the bank' : 'Saved as draft for your review',
    // When to remind the team if the draft is still unsubmitted (never in the past)
    reminderAt: new Date(Math.max(
      Date.now() + 60 * 1000,
      sig.dueByIso ? Date.parse(sig.dueByIso) - (Number(cfg.reminderHoursBeforeDeadline) || 48) * 3600 * 1000 : Date.now() + 60 * 1000,
    )).toISOString(),
    recommendation: ai.recommendation,
    winLikelihood: ai.win_likelihood,
    rationale: ai.rationale,
    missingEvidence: Array.isArray(ai.missing_evidence) ? ai.missing_evidence : [],
  },
}];

